def is_type_b(N):
    # G[n] is True if the player whose turn it is to move from n wins.
    G = [False] * (N + 1)
    # The player who writes N wins.
    # So if n+1 == N or 2*n == N, the current player wins.
    # We compute G[n] from n = N-1 down to 1.
    for n in range(N - 1, 0, -1):
        # Possible moves: n+1 and 2*n
        can_move_to_lose = False

        # Move to n+1
        if n + 1 == N:
            can_move_to_lose = True
        elif n + 1 < N:
            if not G[n+1]:
                can_move_to_lose = True

        # Move to 2*n
        if not can_move_to_lose:
            if 2 * n == N:
                can_move_to_lose = True
            elif 2 * n < N:
                if not G[2*n]:
                    can_move_to_lose = True

        G[n] = can_move_to_lose

    # N is type B if player B wins, and B moves from n=1.
    # So B wins if G[1] is True.
    return G[1]

